"""Source-only assistant preparation. Never executes a retained Skill."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent

def ev(case, path, start, end=None):
    end = start if end is None else end
    lines = (ROOT / 'cases' / case / 'source' / path).read_text(encoding='utf-8-sig').splitlines()
    assert 1 <= start <= end <= len(lines), (case, path, start, end)
    return {'path': path, 'start_line': start, 'end_line': end,
            'quote': '\n'.join(lines[start-1:end])}

def ledger(number):
    case = f'real-{number:03}'
    d = json.loads((ROOT / 'cases' / case / 'reference.template.json').read_text(encoding='utf-8'))
    m = json.loads((ROOT / 'cases' / case / 'source-manifest.json').read_text(encoding='utf-8'))
    d.update(grading_schema_version='skillflow-real-comparison-grading-v2', state='assistant_draft',
             human_verified=False, coverage_state='complete_for_human_verification',
             preparation_limit='Source-only assistant preparation; two actual independent human checks remain required. No target execution or target-result claim.',
             reviewed_files=[f['path'] for f in m['files']],
             reviewed_file_metadata=[{'path': f['path'], 'sha256': f['sha256'],
                              'physical_lines': len((ROOT/'cases'/case/'source'/f['path']).read_text(encoding='utf-8-sig').splitlines()),
                              'review_state': 'read_completely_in_source_bundle'} for f in m['files']],
             coverage_notes=[], remaining_disputes=[])
    return d

def add(d, group, ident, statement, refs, **extra):
    d[group].append({'id': ident, 'statement': statement,
                     'evidence': [ev(d['case_id'], *ref) for ref in refs], **extra})

def finish(d, empty_reason=None):
    # Each receiving point, necessary use, unknown, preservation obligation and
    # supported excess receives its own source-grounded mandatory check.
    for group in ('receiving_points', 'necessary_sensitive_uses', 'unknowns', 'preservation_checks', 'supported_excesses'):
        for f in d[group]:
            if group == 'supported_excesses':
                f['excess_kind'] = ('excess_payload_on_necessary_action' if f['id'] == 'excess-008-model-token' else 'unnecessary_action_exposure')
            stratum = {'necessary_sensitive_uses': 'necessary_sensitive_use', 'unknowns': 'source_uncertainty'}.get(group, f.get('excess_kind', 'other'))
            d['mandatory_checks'].append({'id': 'check-'+f['id'], 'category': group,
                'stratum': stratum, 'obligation': f['statement'], 'reference_item_id': f['id'], 'evidence': f['evidence']})
    if not d['supported_excesses']:
        assert empty_reason
        d['supported_excesses_coverage_reason'] = empty_reason
    d['remaining_disputes'] = [{'reference_item_id': f['id'], 'statement': f['statement'], 'evidence': f['evidence']} for f in d['unknowns']]
    seen = set()
    for group in ('declared_purpose','required_behavior','implementation_choices','receiving_points','necessary_sensitive_uses','supported_excesses','unknowns','preservation_checks'):
        for f in d[group]:
            for e in f['evidence']:
                key = (e['path'],e['start_line'],e['end_line'])
                if key not in seen:
                    d['source_citations'].append(e)
                    seen.add(key)
    p = OUT / (d['case_id']+'.json')
    if p.exists():
        raise FileExistsError('Preserve existing drafts: '+str(p))
    p.write_text(json.dumps(d, ensure_ascii=False, indent=2)+'\n',encoding='utf-8')

