add(d,'receiving_points','rp-005-route-report','Optional route returns selected model/tier and rejected model reasons under the supplied policy/capability constraints. It does not activate a model or run inference, and requests no secret value from ambient environment.', [('scripts/optimizer_core.py',19,62),('scripts/optimizer.py',75,80),('references/PROVIDERS.md',3,18)], boundary_type='model_observe', recipient='routing explanation model')
add(d,'receiving_points','rp-005-context-report','Optional context command reads named files locally and returns ordinal-prefixed basenames, character/token estimates and duplicateOf relationships, not raw instruction text. Duplicate detection is computed locally over normalized content.', [('scripts/optimizer.py',120,127),('scripts/optimizer_core.py',143,154)], boundary_type='model_observe', recipient='agent-processing model')
