add(d,'necessary_sensitive_uses','need-006-identity','Wallet/agent identities, endpoints, URI and rating values may identify an operator or infrastructure, yet they are the declared registry/reputation function inputs and outputs. No independent instruction defines additional confidentiality restrictions or a narrower required metadata subset.', [('SKILL.md',21,40),('index.js',68,75),('index.js',132,141)])
