add(d,'unknowns','unknown-007-doc-code','Some documented whole-market examples conflict with CLI-required ts_code on daily/weekly/monthly, and futures references include helpers not dispatched by main. Preserve these limits rather than invent successful execution of every example or treating them as simultaneous data collection.', [('SKILL.md',85,93),('scripts/market.py',372,391),('scripts/market.py',188,212),('scripts/market.py',491,521)])
