add(d,'implementation_choices','impl-008-curl','The retained source is documentation with curl/JSON examples and no executable wrapper or explicit local result isolation. Curl returns its API response normally; EM02/EM03 retain possible model observation of returned content when an agent runs these calls.', [('skill.md',62,65),('skill.md',564,575)], runtime_rules=['EM02','EM03'])
add(d,'receiving_points','rp-008-account','Account-info GET sends the selected account ID, requested name/status/currency/timezone/spend fields and Bearer token to graph.facebook.com/v25.0. Returned account fields can be observed by the agent model; no unrelated accounts are implied.', [('skill.md',54,65)], boundary_type='network_send / model_observe of response', recipient='Meta Graph API; agent-processing model for response')
